function chartImageSVG(card){
 const e=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 const dark=document.body.classList.contains('dark'),bg=dark?'#15223a':'#ffffff',ink=dark?'#e5edfc':'#172b4d',muted=dark?'#a8b9d2':'#5d708c';let body='',height=600;
 const title=card.querySelector('h3,h2')?.textContent||'Market chart';
 const text=(x,y,value,size=14,color=ink,anchor='start')=>`<text x="${x}" y="${y}" fill="${color}" font-family="Arial,sans-serif" font-size="${size}" text-anchor="${anchor}">${e(value)}</text>`;
 const svg=card.querySelector('svg.scatter,svg.overlay-chart,svg.annual-chart');
 if(svg){const clone=svg.cloneNode(true),originals=[svg,...svg.querySelectorAll('*')],copies=[clone,...clone.querySelectorAll('*')];originals.forEach((node,i)=>{const style=getComputedStyle(node);for(const key of ['fill','stroke','stroke-width','stroke-dasharray','font-size','font-family','font-weight','opacity'])copies[i].style.setProperty(key,style.getPropertyValue(key));copies[i].style.animation='none';copies[i].style.transition='none'});clone.querySelectorAll('g[pointer-events="none"]:not(.finance-time-grid):not(.finance-endpoints)').forEach(n=>n.remove());clone.setAttribute('x','20');clone.setAttribute('y','95');clone.setAttribute('width','1160');const vb=svg.viewBox.baseVal;const h=1160*vb.height/vb.width;clone.setAttribute('height',h);body=new XMLSerializer().serializeToString(clone);height=h+180;const legend=[...card.querySelectorAll('.overlay-toggle')].map(b=>b.textContent.trim()).join('   ·   ');if(legend)body+=text(28,height-55,legend,12);}
 else if(card.querySelector('.stock-treemap')){const map=card.querySelector('.stock-treemap'),r=map.getBoundingClientRect();height=650;body=[...map.querySelectorAll('.treemap-tile')].map(tile=>{const b=tile.getBoundingClientRect(),x=24+(b.left-r.left)/r.width*1152,y=95+(b.top-r.top)/r.height*480,w=b.width/r.width*1152,h=b.height/r.height*480;const color=getComputedStyle(tile).backgroundColor,font=Math.max(9,Math.min(26,parseFloat(getComputedStyle(tile.querySelector('.tile-symbol')).fontSize)*1152/r.width));return `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${color}" stroke="#d5dae1" stroke-width=".5"/>`+text(x+w/2,y+h/2-6,tile.querySelector('.tile-symbol').textContent,font,'#ffffff','middle')+text(x+w/2,y+h/2+font,tile.querySelector('.tile-change').textContent,font*.8,'#ffffff','middle')}).join('');body+=text(24,605,'Area = market cap · Color = daily change · '+card.querySelector('#chart-sector')?.value,12,muted);}
 else if(card.querySelector('.chart-bar-list')){const bars=[...card.querySelectorAll('.interactive-bar')];height=150+bars.length*42;body=bars.map((bar,i)=>{const y=104+i*42,label=bar.querySelector('.bar-company>span:last-child').textContent,value=bar.querySelector('b').textContent,width=parseFloat(bar.querySelector('.bar-fill').style.width)/100*610;return text(24,y+16,label,13)+`<rect x="330" y="${y}" width="610" height="18" rx="3" fill="${dark?'#203755':'#edf3fc'}"/><rect x="330" y="${y}" width="${width}" height="18" rx="3" fill="#3d79ca"/>`+text(1168,y+16,value,13,ink,'end')}).join('');}
 else if(card.querySelector('.donut')){const entries=[...card.querySelectorAll('[data-chart-sector]')];let angle=-Math.PI/2;body=entries.map((entry,i)=>{const pct=parseFloat(entry.querySelector('b').textContent),next=angle+pct/100*2*Math.PI,color=getComputedStyle(entry.querySelector('i')).backgroundColor;const x1=260+175*Math.cos(angle),y1=310+175*Math.sin(angle),x2=260+175*Math.cos(next),y2=310+175*Math.sin(next),path=`M260,310 L${x1},${y1} A175,175 0 ${pct>50?1:0},1 ${x2},${y2} Z`;angle=next;return `<path d="${path}" fill="${color}"/>`+`<rect x="545" y="${108+i*30}" width="10" height="10" rx="2" fill="${color}"/>`+text(567,118+i*30,entry.querySelector('span').textContent,13)+text(1130,118+i*30,pct.toFixed(1)+'%',13,ink,'end')}).join('')+`<circle cx="260" cy="310" r="125" fill="${bg}"/>`+text(260,310,entries.length,32,ink,'middle')+text(260,335,'sectors',13,muted,'middle');}
 else throw Error('No exportable chart data');
 const subtitle=card.id==='chart-scatter'?`${document.querySelector('#scatter-industry')?.value} · ${card.querySelector('.coverage-chip')?.textContent}`:card.querySelector('p')?.textContent||'';
 return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="${height}" viewBox="0 0 1200 ${height}"><rect width="1200" height="${height}" fill="${bg}"/>${text(24,36,title,22)}${text(24,65,subtitle.slice(0,160),11,muted)}${body}${text(24,height-18,'IndiaStockView · Snapshot data · Source periods vary · '+new Date().toLocaleDateString('en-GB'),10,muted)}</svg>`;
}
async function downloadChartImage(card,type,button){button.disabled=true;try{const source=chartImageSVG(card),blob=new Blob([source],{type:'image/svg+xml;charset=utf-8'});let output=blob;if(type==='png'){const img=new Image(),url=URL.createObjectURL(blob);try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas');canvas.width=img.naturalWidth*2;canvas.height=img.naturalHeight*2;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);output=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!output)throw Error('PNG conversion failed')}finally{URL.revokeObjectURL(url)}}const a=document.createElement('a'),url=URL.createObjectURL(output);a.href=url;a.download='india-stock-view-'+(card.querySelector('h3,h2')?.textContent||'chart').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.'+type;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Chart downloaded as '+type.toUpperCase())}catch{toast('Could not export this chart. Please try SVG.')}finally{button.disabled=false}}
function installChartDownloads(){document.querySelectorAll('.charts-workspace>.card,.compare-overlay,.stock-chart-card').forEach(card=>{if(card.querySelector(':scope>.chart-image-actions')||!card.querySelector('svg,.stock-treemap,.chart-bar-list,.donut'))return;const actions=document.createElement('div');actions.className='chart-image-actions';actions.setAttribute('aria-label','Download chart image');for(const type of ['png','svg']){const button=document.createElement('button');button.textContent='↓ '+type.toUpperCase();button.title='Download chart as '+type.toUpperCase();button.setAttribute('aria-label',button.title);button.onclick=()=>downloadChartImage(card,type,button);actions.append(button)}card.append(actions)})}
new MutationObserver(installChartDownloads).observe(document.querySelector('#content'),{childList:true,subtree:true});
